import fs from 'node:fs';
import assert from 'node:assert/strict';

// Explicit dispatch only. No customer phone, no Meta endpoint, no model request.
// All writes target UUIDs generated by our disposable QA setup transaction.
const ref=process.env.SUPABASE_PROJECT_REF;
const token=process.env.SUPABASE_ACCESS_TOKEN||process.env.SUPABASE_MANAGEMENT_TOKEN;
if(process.env.DABBIR_REAL_DB_ACK!=='ISOLATED_QA_TRANSACTIONS'||ref!=='fphpoysqdsceniwduxjq'||!token)throw Error('REAL_DB_PROOF_NOT_AUTHORIZED_OR_CONFIGURED');
const evidence={scope:'Production PostgreSQL, isolated QA tenant, real semantic RPCs; synthetic presentation receipt; no Meta transport',started_at:new Date().toISOString()};
const uuid=/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/;
const prefix=`begin; set local statement_timeout='25s'; set local request.jwt.claim.role='service_role'; set local request.jwt.claims='{"role":"service_role"}';`;
async function sql(query){
 const response=await fetch(`https://api.supabase.com/v1/projects/${ref}/database/query`,{method:'POST',headers:{authorization:`Bearer ${token}`,'content-type':'application/json'},body:JSON.stringify({query}),signal:AbortSignal.timeout(35000)});
 const body=await response.json();
 if(!response.ok){const message=String(body.message||''),code=message.match(/SEMANTIC_[A-Z_]+|QA_[A-Z_]+/);const kind=/deadlock detected/i.test(message)?'DB_DEADLOCK':/statement timeout/i.test(message)?'DB_STATEMENT_TIMEOUT':/permission denied/i.test(message)?'DB_PERMISSION_DENIED':`DB_QUERY_HTTP_${response.status}`;throw Object.assign(Error(code?.[0]||kind),{code:code?.[0]||kind});}
 if(!Array.isArray(body))throw Error('DB_RESULT_INVALID');return body;
}
let fixture;const inFlight=[];
try{
 evidence.phase='setup';fixture=(await sql(fs.readFileSync(new URL('../test/fixtures/understanding/production-concurrency-setup.sql',import.meta.url),'utf8')))[0]?.fixture;
 assert.ok(fixture&&Object.values(fixture).every(v=>typeof v==='string'&&uuid.test(v)),'fixture identifiers are server generated UUIDs');
 const {batch,lock,business,past,conversation}=fixture;
 evidence.phase='concurrent_booking';
 // Acquire locks through the application's own guard, in its actual order.
 // Locking the batch first would create an artificial reverse-order deadlock.
 const execute=i=>sql(`${prefix} ${i===0?`/* DABBIR_CONCURRENT_HOLDER */ select public.dabbir_semantic_assert_current_v2('${batch}','${lock}',1); select pg_sleep(8);`:''} select jsonb_build_object('session',pg_backend_pid(),'started',transaction_timestamp(),'result',public.dabbir_semantic_execute_v2('${batch}','${lock}',1,'CREATE_BOOKING'),'finished',clock_timestamp()) as evidence; commit;`);
 const holder=execute(0);inFlight.push(holder);holder.catch(()=>{});
 let active=false;
 for(let i=0;i<8&&!active;i++){
  active=Number((await sql("select count(*) as active from pg_stat_activity where pid<>pg_backend_pid() and state='active' and query like '%DABBIR_CONCURRENT_HOLDER%'"))[0].active)>0;
 }
 assert.ok(active,'holder transaction must be active before competitors start');
 const competitors=[execute(1),execute(2)];inFlight.push(...competitors);
 const settled=await Promise.allSettled([holder,...competitors]);
 if(settled.some(x=>x.status==='rejected'))throw settled.find(x=>x.status==='rejected').reason;
 const outcomes=settled.map(x=>x.value);
 evidence.concurrent_booking=outcomes.map(x=>x[0].evidence);
 assert.equal(new Set(evidence.concurrent_booking.map(x=>x.session)).size,3);
 assert.ok(evidence.concurrent_booking.slice(1).every(x=>Date.parse(x.started)<Date.parse(evidence.concurrent_booking[0].finished)),'all independent transaction intervals must overlap');
 assert.equal(new Set(evidence.concurrent_booking.map(x=>x.result.appointment_id)).size,1);
 assert.equal(evidence.concurrent_booking.filter(x=>x.result.idempotent_replay===false).length,1);
 const readback=(await sql(`select (select count(*) from public.dabbir_appointments where business_id='${business}' and id<>'${past}') as bookings,(select count(*) from public.dabbir_ai_action_ledger where business_id='${business}') as ledger_rows;`))[0];
 assert.equal(Number(readback.bookings),1);assert.equal(Number(readback.ledger_rows),1);evidence.readback=readback;
 // Exercise the actual send reservation under overlapping transactions. This
 // script has no Meta transport: should_send authorizes one attempt, not delivery.
 evidence.phase='concurrent_outbound';
 await sql(`${prefix} update public.dabbir_customers set channel_handle='qa-synthetic' where business_id='${business}' and id=(select customer_id from public.dabbir_conversations where id='${conversation}' and business_id='${business}'); update public.dabbir_whatsapp_connections set status='connected' where business_id='${business}' and waba_id like 'qa-%' and access_token_ciphertext='SYNTHETIC-NOT-A-CREDENTIAL'; commit;`);
 const reserve=i=>sql(`${prefix} ${i===0?`/* DABBIR_OUTBOUND_HOLDER */ select public.dabbir_semantic_assert_current_v2('${batch}','${lock}',1); select pg_sleep(8);`:''} select jsonb_build_object('session',pg_backend_pid(),'started',transaction_timestamp(),'result',public.dabbir_semantic_reserve_outbound_v2('${batch}','${lock}',1,'wa-understanding:${batch}:qa-proof',repeat('b',64),'Synthetic no-transport proof'),'finished',clock_timestamp()) as evidence; commit;`);
 const outboundHolder=reserve(0);inFlight.push(outboundHolder);outboundHolder.catch(()=>{});
 active=false;
 for(let i=0;i<8&&!active;i++)active=Number((await sql("select count(*) as active from pg_stat_activity where pid<>pg_backend_pid() and state='active' and query like '%DABBIR_OUTBOUND_HOLDER%'"))[0].active)>0;
 assert.ok(active,'outbound holder must be active before competitors start');
 const outboundCompetitors=[reserve(1),reserve(2)];inFlight.push(...outboundCompetitors);
 const outbound=await Promise.allSettled([outboundHolder,...outboundCompetitors]);
 if(outbound.some(x=>x.status==='rejected'))throw outbound.find(x=>x.status==='rejected').reason;
 evidence.concurrent_outbound=outbound.map(x=>{const row=x.value[0].evidence;return {session:row.session,started:row.started,finished:row.finished,reservation_id:row.result.reservation_id,should_send:row.result.should_send};});
 assert.equal(new Set(evidence.concurrent_outbound.map(x=>x.session)).size,3);
 assert.ok(evidence.concurrent_outbound.slice(1).every(x=>Date.parse(x.started)<Date.parse(evidence.concurrent_outbound[0].finished)));
 assert.equal(new Set(evidence.concurrent_outbound.map(x=>x.reservation_id)).size,1);
 assert.equal(evidence.concurrent_outbound.filter(x=>x.should_send===true).length,1);
 evidence.meta_delivery_proven=false;
 // A is already interpreted. B/C arrive before A's delayed next operation.
 // This tests the existing revision trigger against an old decision overwrite.
 evidence.phase='late_decision';
 const late=sql(`${prefix} /* DABBIR_LATE_DECISION */ select pg_sleep(8); select public.dabbir_semantic_assert_current_v2('${batch}','${lock}',1); commit;`).then(()=>({blocked:false}),error=>({blocked:error.code==='SEMANTIC_SUPERSEDED',error:error.code}));
 inFlight.push(late);
 const inserted=await sql(`${prefix} insert into public.dabbir_messages(business_id,conversation_id,sender_type,body,simulated) values('${business}','${conversation}','customer','لا قصدي عقب باجر',false),('${business}','${conversation}','customer','الساعة 19:00',false); select understanding_revision from public.dabbir_conversations where id='${conversation}'; commit;`);
 evidence.late_decision=await late;assert.equal(evidence.late_decision.blocked,true);assert.equal(Number(inserted[0].understanding_revision),3);
 evidence.message_revision=Number(inserted[0].understanding_revision);
 evidence.verdict='PASS';
}catch(error){evidence.verdict='FAIL';evidence.error=error.code||error.message;process.exitCode=1;}
finally{
 await Promise.allSettled(inFlight);
 if(fixture){
  const {business,owner}=fixture;
  try{
   const cleanup=await sql(`${prefix} do $cleanup$ begin if not exists(select 1 from public.dabbir_businesses where id='${business}' and name='DABBIR AI QA concurrency 20260910') or not exists(select 1 from auth.users where id='${owner}' and email='qa-activity-${owner}@example.invalid') then raise exception 'QA_SCOPE_MISMATCH'; end if; delete from public.dabbir_whatsapp_outbound_reservations where business_id='${business}' and recipient_handle='qa-synthetic'; delete from public.dabbir_whatsapp_connections where business_id='${business}' and waba_id like 'qa-%' and access_token_ciphertext='SYNTHETIC-NOT-A-CREDENTIAL'; perform public.dabbir_qa_cleanup_business('${business}'); insert into public.account_access_state(user_id,status,reason,updated_at) values('${owner}','deleted','DABBIR_ACCOUNT_DELETED',now()) on conflict(user_id) do update set status='deleted',reason='DABBIR_ACCOUNT_DELETED',updated_at=now(); delete from public.dabbir_user_accounts where user_id='${owner}'; delete from auth.users where id='${owner}' and email='qa-activity-${owner}@example.invalid'; end $cleanup$; select (select count(*) from public.dabbir_businesses where id='${business}') as remaining_business,(select count(*) from auth.users where id='${owner}') as remaining_owner; commit;`);
   evidence.cleanup=cleanup[0];assert.equal(Number(cleanup[0].remaining_business),0);assert.equal(Number(cleanup[0].remaining_owner),0);
  }catch(error){evidence.cleanup={error:error.code||error.message,fixture_business:business,fixture_owner:owner};evidence.verdict='FAIL';process.exitCode=1;}
 }
 evidence.finished_at=new Date().toISOString();
 fs.mkdirSync('test-results/brain-real-db',{recursive:true});fs.writeFileSync('test-results/brain-real-db/evidence.json',JSON.stringify(evidence,null,2)+'\n');
 console.log(JSON.stringify(evidence,null,2));
}
